async function api(path, payload) {
  const response=await fetch(path,{method:payload ? "POST" : "GET",headers:payload ? {"Content-Type":"application/json"} : {},body:payload ? JSON.stringify(payload) : undefined});
  const result=await response.json(); if(!response.ok) throw new Error(result.error || `Erro HTTP ${response.status}`); return result;
}
async function task(button, message, work) {
  if(button?.disabled) return;
  const previous=button?.innerHTML;
  if(button){button.disabled=true;button.setAttribute("aria-busy","true");button.textContent="Calculando…";}
  status(message);
  try {return await work();} catch(error){notify(error.message,true);} finally {if(button){button.disabled=false;button.removeAttribute("aria-busy");button.innerHTML=previous;}}
}
