function toCSV(rows, columns) {const quote=v=>'"'+String(v??"").replace(/"/g,'""')+'"';return columns.map(quote).join(",")+"\n"+rows.map(r=>columns.map(c=>quote(r[c])).join(",")).join("\n")+"\n";}
function option(value,label) {const opt=document.createElement('option');opt.value=value;opt.textContent=label;return opt;}
