const numericFields=new Set(["resolution","gain","bins","radius","min_neighbors","k","edge_threshold","seed","ball_radius","max_landmarks"]);
function readConfig(){const cfg={};for(const key of configFields)cfg[key]=numericFields.has(key)?Number($(key).value):$(key).value;cfg.columns=[...$('columns').querySelectorAll('input:checked')].map(e=>e.value);return cfg;}
