function updateControls(){ $('resolution-value').textContent=$('resolution').value;const gain=Number($('gain').value);$('gain-value').textContent=fmt(gain,1)+"×";$('overlap-hint').textContent=fmt(100*(1-1/gain),0)+"% de sobreposição entre intervalos";const ball=$('algorithm').value==='ball';$('ball-section').hidden=!ball;$('ball-section').open=ball;$('lens-section').hidden=ball;$('cluster-section').hidden=ball;document.querySelectorAll('.cluster-param').forEach(n=>n.hidden=!n.dataset.for.split(' ').includes($('cluster').value));$('jaccard-field').hidden=$('nerve').value!=='jaccard';}
