function showTooltip(event,node){const info=colorInfo();$('tooltip').innerHTML=`<b>Nó ${node.id}</b>${node.size} linhas · ${node.degree} conexões<br>${esc($('color').selectedOptions[0].text)}: ${esc(info.numeric?fmt(info.values[node.id-1]):info.values[node.id-1])}`;const rect=$('graph-container').getBoundingClientRect();$('tooltip').style.left=Math.min(rect.width-200,Math.max(8,event.clientX-rect.left+12))+'px';$('tooltip').style.top=Math.max(8,event.clientY-rect.top-65)+'px';$('tooltip').hidden=false;}
function rowColor(rowId,info){const name=info.name;if(!name.startsWith('__'))return info.color(state.dataset.rows[rowId-1][name]);if(name==='__component'){const node=state.model.nodes.find(n=>n.members.includes(rowId));return info.color(node?'Componente '+node.component:null);}return '#278d9f';}
let scatterPoints=[];
function renderScatter(){if(!state.model)return;const svg=$('scatter');svg.replaceChildren();const raw=state.model.projection,xs=raw.map(p=>p.x),ys=raw.map(p=>p.y),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);const scale=Math.min(780/Math.max(x1-x0,1e-10),150/Math.max(y1-y0,1e-10));scatterPoints=raw.map(p=>({id:p.id,x:450+(p.x-(x0+x1)/2)*scale,y:92+(p.y-(y0+y1)/2)*scale}));svg.append(element('line',{x1:25,y1:92,x2:875,y2:92,class:'chart-grid'}),element('line',{x1:450,y1:10,x2:450,y2:183,class:'chart-grid'}),element('text',{x:868,y:188,class:'chart-label'},'PC1'),element('text',{x:455,y:14,class:'chart-label'},'PC2'));
  const selected=state.selected.size>0,info=colorInfo();for(const point of scatterPoints){const isSelected=state.selected.has(point.id);const circle=element('circle',{cx:point.x,cy:point.y,r:isSelected?3.1:2.2,fill:rowColor(point.id,info),opacity:selected&&!isSelected?.16:.7,class:'scatter-point','data-row':point.id});svg.append(circle);}}
function selectNode(node,add){const ids=new Set(add?state.selected:[]);const already=node.members.every(id=>ids.has(id));for(const id of node.members)if(add&&already)ids.delete(id);else ids.add(id);selectRows([...ids]);}
