function renderPreprocessing(){if(!state.model)return;$('preprocessing').innerHTML='<div class="table-wrap"><table><thead><tr><th>Variável</th><th>Imputações</th><th>Centro</th><th>Escala</th></tr></thead><tbody>'+state.model.preprocessing.map(r=>`<tr><td>${esc(r.column)}</td><td>${r.imputed}</td><td>${fmt(r.offset)}</td><td>${fmt(r.scale)}</td></tr>`).join('')+'</tbody></table></div>';}
function renderTable(){if(!state.dataset)return;const ds=state.dataset,query=$('data-search').value.toLocaleLowerCase(),only=$('only-selected').checked;const filtered=ds.rows.map((row,i)=>({row,id:i+1})).filter(({row,id})=>(!only||state.selected.has(id))&&(!query||Object.values(row).some(v=>String(v??'').toLocaleLowerCase().includes(query))));const total=filtered.length,pages=Math.max(1,Math.ceil(total/40));state.page=Math.min(state.page,pages-1);const rows=filtered.slice(state.page*40,state.page*40+40);$('data-description').textContent=ds.name+' · valores originais, antes do pré-processamento';$('table-count').textContent=fmt(total,0)+' linhas';$('quality').innerHTML=ds.columns.map(c=>`<span><b>${esc(c.name)}</b> · ${c.type==='numeric'?'numérica':'categórica'} · ${c.missing} ausentes</span>`).join('');$('data-table').innerHTML=`<table><thead><tr><th>Linha</th>${ds.columns.map(c=>`<th>${esc(c.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(({row,id})=>`<tr data-row="${id}" tabindex="0" class="${state.selected.has(id)?'selected-row':''}"><td>${id}</td>${ds.columns.map(c=>`<td>${esc(typeof row[c.name]==='number'?fmt(row[c.name],5):row[c.name]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('page-label').textContent=`${state.page+1} / ${pages}`;$('prev-page').disabled=state.page===0;$('next-page').disabled=state.page===pages-1;
  $('data-table').querySelectorAll('tr[data-row]').forEach(tr=>{const select=e=>{const id=Number(tr.dataset.row);const ids=e.shiftKey?new Set(state.selected):new Set();ids.has(id)?ids.delete(id):ids.add(id);selectRows([...ids]);};tr.addEventListener('click',select);tr.addEventListener('keydown',e=>{if(e.key==='Enter')select(e);});});
}

// Graph navigation and selection use SVG coordinates, independent of screen size.
function svgPoint(svg,event){const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;return point.matrixTransform(svg.getScreenCTM().inverse());}
function applyViewbox(){$('graph').setAttribute('viewBox',state.viewbox.join(' '));}
function zoom(factor,center){const [x,y,w,h]=state.viewbox,c=center||{x:x+w/2,y:y+h/2},neww=Math.max(90,Math.min(3600,w*factor)),newh=neww*h/w;state.viewbox=[c.x-(c.x-x)*neww/w,c.y-(c.y-y)*newh/h,neww,newh];applyViewbox();}
function fitGraph(){if(!state.positions.length)return;const xs=state.positions.map(p=>p.x),ys=state.positions.map(p=>p.y),rect=$('graph').getBoundingClientRect();let w=Math.max(100,Math.max(...xs)-Math.min(...xs)+90),h=Math.max(100,Math.max(...ys)-Math.min(...ys)+90);const aspect=rect.width/Math.max(1,rect.height);if(w/h>aspect)h=w/aspect;else w=h*aspect;state.viewbox=[(Math.min(...xs)+Math.max(...xs)-w)/2,(Math.min(...ys)+Math.max(...ys)-h)/2,w,h];applyViewbox();}
let dragMoved=false,scatterMoved=false,gesture=null;
function nodeDrag(event,node){if(event.button!==0)return;event.stopPropagation();cancelAnimationFrame(state.layoutFrame);dragMoved=false;const start=svgPoint($('graph'),event),position={...state.positions[node.id-1]};gesture={kind:'node',node,start,position,pointer:event.pointerId,screen:{x:event.clientX,y:event.clientY},add:event.shiftKey||event.ctrlKey||event.metaKey};$('graph').setPointerCapture(event.pointerId);}
$('graph').addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('.node'))return;dragMoved=false;const start=svgPoint($('graph'),event);gesture={kind:state.mode,start,box:[...state.viewbox],pointer:event.pointerId,screen:{x:event.clientX,y:event.clientY},add:event.shiftKey};$('graph').setPointerCapture(event.pointerId);if(state.mode==='select'){gesture.rect=element('rect',{class:'brush',x:start.x,y:start.y,width:0,height:0});$('graph').append(gesture.rect);}});
$('graph').addEventListener('pointermove',event=>{if(!gesture||gesture.pointer!==event.pointerId)return;const point=svgPoint($('graph'),event),moved=Math.hypot(event.clientX-gesture.screen.x,event.clientY-gesture.screen.y)>3;if(moved)dragMoved=true;if(gesture.kind==='node'){state.positions[gesture.node.id-1]={x:gesture.position.x+point.x-gesture.start.x,y:gesture.position.y+point.y-gesture.start.y};updateGraphPositions();$('tooltip').hidden=true;}else if(gesture.kind==='pan'){const rect=$('graph').getBoundingClientRect();const dx=(event.clientX-gesture.screen.x)*gesture.box[2]/rect.width,dy=(event.clientY-gesture.screen.y)*gesture.box[3]/rect.height;state.viewbox=[gesture.box[0]-dx,gesture.box[1]-dy,gesture.box[2],gesture.box[3]];applyViewbox();}else if(gesture.rect){gesture.end=point;const attrs={x:Math.min(point.x,gesture.start.x),y:Math.min(point.y,gesture.start.y),width:Math.abs(point.x-gesture.start.x),height:Math.abs(point.y-gesture.start.y)};for(const [key,value]of Object.entries(attrs))gesture.rect.setAttribute(key,value);}});
$('graph').addEventListener('pointerup',event=>{if(!gesture)return;if(gesture.kind==='node'&&!dragMoved)selectNode(gesture.node,gesture.add);if(gesture.kind==='select'&&gesture.end&&state.model){const a=gesture.start,b=gesture.end,ids=new Set(gesture.add?state.selected:[]);state.positions.forEach((p,i)=>{if(p.x>=Math.min(a.x,b.x)&&p.x<=Math.max(a.x,b.x)&&p.y>=Math.min(a.y,b.y)&&p.y<=Math.max(a.y,b.y))state.model.nodes[i].members.forEach(id=>ids.add(id));});selectRows([...ids]);}gesture.rect?.remove();gesture=null;setTimeout(()=>dragMoved=false,0);});
$('graph').addEventListener('pointercancel',()=>{gesture?.rect?.remove();gesture=null;});
$('graph').addEventListener('wheel',event=>{event.preventDefault();zoom(event.deltaY>0?1.1:.9,svgPoint($('graph'),event));},{passive:false});
let scatterGesture;
$('scatter').addEventListener('pointerdown',event=>{if(event.button!==0)return;scatterMoved=false;scatterGesture={start:svgPoint($('scatter'),event),screen:{x:event.clientX,y:event.clientY},add:event.shiftKey,row:Number(event.target.dataset.row)||null};$('scatter').setPointerCapture(event.pointerId);});
$('scatter').addEventListener('pointermove',event=>{if(!scatterGesture)return;if(Math.hypot(event.clientX-scatterGesture.screen.x,event.clientY-scatterGesture.screen.y)<4)return;scatterMoved=true;const end=svgPoint($('scatter'),event),start=scatterGesture.start;scatterGesture.end=end;if(!scatterGesture.rect){scatterGesture.rect=element('rect',{class:'brush'});$('scatter').append(scatterGesture.rect);}for(const [k,v]of Object.entries({x:Math.min(start.x,end.x),y:Math.min(start.y,end.y),width:Math.abs(end.x-start.x),height:Math.abs(end.y-start.y)}))scatterGesture.rect.setAttribute(k,v);});
$('scatter').addEventListener('pointerup',()=>{if(scatterGesture?.end){const {start:a,end:b,add}=scatterGesture,ids=new Set(add?state.selected:[]);scatterPoints.forEach(p=>{if(p.x>=Math.min(a.x,b.x)&&p.x<=Math.max(a.x,b.x)&&p.y>=Math.min(a.y,b.y)&&p.y<=Math.max(a.y,b.y))ids.add(p.id);});selectRows([...ids]);}else if(scatterGesture?.row){const ids=new Set(scatterGesture.add?state.selected:[]);ids.has(scatterGesture.row)?ids.delete(scatterGesture.row):ids.add(scatterGesture.row);selectRows([...ids]);}scatterGesture?.rect?.remove();scatterGesture=null;setTimeout(()=>scatterMoved=false,0);});
$('scatter').addEventListener('pointercancel',()=>{scatterGesture?.rect?.remove();scatterGesture=null;});

function chartFrame(width=420,height=280,xlabel='Escala',ylabel='Valor'){
  const svg=element('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':ylabel+' por '+xlabel});
  const box={left:45,top:20,right:width-20,bottom:height-38};
  for(let i=0;i<=4;i++){const x=box.left+(box.right-box.left)*i/4,y=box.bottom-(box.bottom-box.top)*i/4;svg.append(element('line',{x1:x,y1:box.top,x2:x,y2:box.bottom,class:'chart-grid'}),element('line',{x1:box.left,y1:y,x2:box.right,y2:y,class:'chart-grid'}));}
  svg.append(element('text',{x:(box.left+box.right)/2,y:height-6,class:'chart-label','text-anchor':'middle'},xlabel),element('text',{x:12,y:(box.top+box.bottom)/2,transform:`rotate(-90 12 ${(box.top+box.bottom)/2})`,class:'chart-label','text-anchor':'middle'},ylabel));
  return {svg,box,x:v=>box.left+v*(box.right-box.left),y:v=>box.bottom-v*(box.bottom-box.top)};
}
function tickLabels(chart,maxX,maxY){for(let i=0;i<=4;i++){chart.svg.append(element('text',{x:chart.x(i/4),y:chart.box.bottom+15,class:'chart-label','text-anchor':'middle'},fmt(maxX*i/4,2)),element('text',{x:chart.box.left-7,y:chart.y(i/4)+3,class:'chart-label','text-anchor':'end'},fmt(maxY*i/4,2)));}}
function plotPH(result){
  const summaries=result.summary.map(s=>`<div><b>${s.features}</b> H${s.dimension}: ${s.finite} barras finitas</div>`).join('');
  $('ph-output').innerHTML=`<div class="result-metrics"><div><b>${result.sample_n} / ${result.source_n}</b>marcos / linhas</div><div><b>${esc(result.coefficients)}</b>coeficientes</div>${summaries}</div><p class="result-note">${esc(result.note)}</p><div class="plot-row"><div class="plot-panel"><h2>Diagrama de persistência</h2><p>Nascimento × morte · H0 azul, H1 violeta, H2 âmbar</p><div id="diagram-plot"></div></div><div class="plot-panel"><h2>Curvas de Betti</h2><p>Número de estruturas presentes em cada escala</p><div id="betti-plot"></div></div></div><div class="plot-panel wide"><h2>Barcode</h2><p>Barras mais persistentes, até 80 por dimensão. Traços pontilhados indicam morte não observada.</p><div id="barcode-plot"></div></div><div class="plot-panel wide"><h2>Resumo por dimensão</h2><p>Entropia = −Σ p log(p), com persistências relativas das barras finitas positivas.</p><div class="table-wrap"><table><thead><tr><th>Dimensão</th><th>Barras finitas positivas</th><th>Persistência máxima</th><th>Entropia · log natural</th></tr></thead><tbody>${result.summary.map(s=>`<tr><td>H${s.dimension}</td><td>${s.finite}</td><td>${fmt(s.max_persistence)}</td><td>${fmt(s.entropy)}</td></tr>`).join('')}</tbody></table></div></div><details class="audit"><summary>Linhas escolhidas como marcos</summary><p class="hint">${result.landmarks.join(', ')}</p></details>`;
  const palette=['#477dbc','#8262b8','#cc8c32'],max=result.threshold*1.12||1,diagram=chartFrame(420,310,'Nascimento','Morte');tickLabels(diagram,max,max);diagram.svg.append(element('line',{x1:diagram.x(0),y1:diagram.y(0),x2:diagram.x(1),y2:diagram.y(1),stroke:'var(--muted)','stroke-dasharray':'4 4'}));
  const infinityY=diagram.y(result.threshold*1.06/max);diagram.svg.append(element('line',{x1:diagram.box.left,y1:infinityY,x2:diagram.box.right,y2:infinityY,stroke:'var(--muted)','stroke-dasharray':'2 4'}),element('text',{x:diagram.box.right,y:infinityY-4,class:'chart-label','text-anchor':'end'},'∞ / censurado'));
  for(const bar of result.bars){const mark=element(bar.death==null?'rect':'circle',bar.death==null?{x:diagram.x(bar.birth/max)-3,y:infinityY-3,width:6,height:6,fill:palette[bar.dimension]}:{cx:diagram.x(bar.birth/max),cy:diagram.y(bar.death/max),r:3.2,fill:palette[bar.dimension],opacity:.65});mark.append(element('title',{},`H${bar.dimension}: ${fmt(bar.birth)} → ${bar.death==null?'∞ / censurado':fmt(bar.death)}`));diagram.svg.append(mark);}$('diagram-plot').append(diagram.svg);
  const maxBetti=Math.max(1,...result.betti.flatMap(c=>c.values)),betti=chartFrame(420,310,'Escala','Betti');tickLabels(betti,result.threshold,maxBetti);
  for(const curve of result.betti){let points='';for(let i=0;i<curve.values.length;i++){const x=betti.x(result.scales[i]/result.threshold),y=betti.y(curve.values[i]/maxBetti);if(i)points+=` ${x},${betti.y(curve.values[i-1]/maxBetti)}`;points+=` ${x},${y}`;}betti.svg.append(element('polyline',{points,fill:'none',stroke:palette[curve.dimension],'stroke-width':2}));}$('betti-plot').append(betti.svg);
  const bars=result.summary.flatMap(summary=>result.bars.filter(b=>b.dimension===summary.dimension).sort((a,b)=>(b.persistence??Infinity)-(a.persistence??Infinity)).slice(0,80)),height=Math.max(100,30+bars.length*4);const barcode=element('svg',{viewBox:`0 0 820 ${height+25}`,role:'img','aria-label':'Barcode de persistência'});bars.forEach((bar,i)=>{const y=15+i*4;barcode.append(element('line',{x1:45+bar.birth/max*750,x2:45+(bar.death??max)/max*750,y1:y,y2:y,stroke:palette[bar.dimension],'stroke-width':2.5,'stroke-dasharray':bar.death==null?'5 3':'none'}));});for(let i=0;i<=4;i++)barcode.append(element('text',{x:45+750*i/4,y:height+15,class:'chart-label','text-anchor':'middle'},fmt(max*i/4,2)));$('barcode-plot').append(barcode);
}
function histogramSVG(feature){const svg=element('svg',{viewBox:'0 0 320 70',role:'img','aria-label':`Distribuição de ${feature.column}: seleção e referência`}),h=feature.histogram,max=Math.max(.01,...h.selected,...h.reference),count=h.selected.length;for(let i=0;i<count;i++){const x=8+i*304/count,w=304/count;svg.append(element('rect',{x,y:57-h.reference[i]/max*48,width:Math.max(1,w*.4),height:h.reference[i]/max*48,fill:'#a3afc0'}),element('rect',{x:x+w*.42,y:57-h.selected[i]/max*48,width:Math.max(1,w*.4),height:h.selected[i]/max*48,fill:'#278d9f'}));}if(h.bounds){svg.append(element('text',{x:8,y:69,class:'chart-label'},fmt(h.bounds[0],2)),element('text',{x:312,y:69,class:'chart-label','text-anchor':'end'},fmt(h.bounds[h.bounds.length-1],2)));}else svg.append(element('text',{x:8,y:69,class:'chart-label'},h.labels.slice(0,5).join(' · ').slice(0,48)));return svg;}
async function runExplain(){if(!state.dataset)return;const selected=[...state.selected],ref=state.groups.find(g=>g.id===$('reference').value),revision=state.revision;
  $('explain-dialog').showModal();$('explain-output').innerHTML='<p class="result-note">Comparando distribuições em Julia…</p>';
  await task($('rerun-explain'),"Executando Explain por permutação…",async()=>{const result=await api('/api/explain',{dataset_id:state.dataset.id,selected,reference:ref?.rows??null,permutations:Number($('permutations').value),seed:state.model?.config.seed??2007});if(revision!==state.revision)return;state.explanation=result;state.explanation.selected=selected;state.explanation.reference=ref?.rows??null;$('explain-summary').textContent=`${result.selected_n} linhas vs. ${result.reference_n} · ${result.permutations} permutações · p mínimo ${fmt(result.min_p,4)}`;$('export-explain').disabled=false;
    $('explain-output').innerHTML=`<p class="result-note">${esc(result.note)}</p><div class="legend"><span class="legend-item"><i class="legend-dot" style="background:#278d9f"></i>Seleção</span><span class="legend-item"><i class="legend-dot" style="background:#a3afc0"></i>Referência</span><span>Ranking por q, seguido de distância entre distribuições</span></div><div class="explain-feature feature-head"><span>Variável</span><span>Distribuições</span><span>Distância</span><span>q (BH)</span></div>`;
    for(const feature of result.features){const row=document.createElement('div');row.className='explain-feature';const info=document.createElement('div');info.innerHTML=`<h3>${esc(feature.column)}</h3><p>${esc(feature.test)}</p><p>${feature.type==='numeric'?`Médias ${fmt(feature.selected_mean)} / ${fmt(feature.reference_mean)} · d = ${fmt(feature.effect)}`:`${feature.selected_n} / ${feature.reference_n} observações`}</p>`;const score=document.createElement('span');score.className='score';score.textContent=fmt(feature.score,3);const q=document.createElement('span');q.className=feature.q<=.05?'q-tag':'score';q.textContent=fmt(feature.q,4);q.title='p = '+fmt(feature.p,4);row.append(info,histogramSVG(feature),score,q);$('explain-output').append(row);}if(!result.features.length)$('explain-output').innerHTML+='<p>Nenhuma variável tem observações suficientes nos dois grupos.</p>';status('Explain pronto. Diferenças exploratórias ordenadas por q.');
  });
}
function renderModels(){const container=$('model-list');container.replaceChildren();for(const model of state.models){const row=document.createElement('div');row.className='model-item';const button=document.createElement('button');button.textContent=model.name;button.className='secondary';button.addEventListener('click',async()=>{setConfig(model.config);switchTab('mapper');await runMapper();});const summary=document.createElement('span');summary.textContent=`${model.summary.nodes} nós · ${model.summary.components} componentes`;const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remover modelo '+model.name);remove.addEventListener('click',()=>{state.models=state.models.filter(m=>m!==model);renderModels();});row.append(button,summary,remove);container.append(row);}}
function requireModel(){if(!state.model)throw new Error('Construa um Mapper primeiro.');return {dataset_id:state.dataset.id,config:state.model.config};}
function scopedTask(button,message,work){const revision=state.revision;return task(button,message,async()=>{const result=await work();if(revision!==state.revision)return null;return result;});}
$('run-ph').addEventListener('click',()=>scopedTask($('run-ph'),'Calculando homologia persistente…',async()=>{const payload=requireModel(),sample=Number($('ph-sample').value),dimension=Number($('ph-dimension').value);const result=await api('/api/persistence',{...payload,sample,dimension,selected:$('ph-scope').value==='selected'?[...state.selected]:null});if(payload.dataset_id!==state.dataset.id)return;state.ph=result;plotPH(result);$('export-ph').disabled=false;status(`Persistência pronta: ${result.sample_n} marcos, métrica ${result.metric}.`);return result;}));
$('ph-dimension').addEventListener('change',()=>{const max=$('ph-dimension').value==='2'?80:300;$('ph-sample').max=max;$('ph-sample').value=Math.min(max,Number($('ph-sample').value));});
$('run-sweep').addEventListener('click',()=>task($('run-sweep'),'Comparando configurações de cobertura…',async()=>{const payload=requireModel(),resolutions=$('sweep-resolutions').value.split(',').map(Number),gains=$('sweep-gains').value.split(',').map(Number);const result=await api('/api/sensitivity',{...payload,resolutions,gains});if(payload.dataset_id!==state.dataset.id)return;$('sweep-output').innerHTML=`<p class="result-note">${esc(result.note)}</p><div class="sweep-grid"></div>`;const max=Math.max(...result.results.map(r=>r.nodes));for(const cell of result.results){const b=document.createElement('button');b.className='sweep-cell';b.innerHTML=`<b>${cell.resolution} intervalos · ${fmt(cell.gain,1)}×</b><p>${cell.nodes} nós · ${cell.edges} conexões</p><div class="sweep-shape"><span style="width:${100*cell.nodes/max}%"></span></div><p>${cell.components} componentes · ${cell.graph_cycles} ciclos</p><p>${fmt(cell.coverage*100,0)}% coberto · ${fmt(cell.elapsed,2)} s</p>`;b.addEventListener('click',async()=>{setConfig({...payload.config,resolution:cell.resolution,gain:cell.gain});switchTab('mapper');await runMapper();});$('sweep-output').querySelector('.sweep-grid').append(b);}status('Varredura concluída. Clique em um modelo para explorá-lo.');}));
