function connectedNodeGroups(nodes,edges){const eligible=new Set(nodes.map(n=>n.id)),adj=new Map(nodes.map(n=>[n.id,[]]));for(const e of edges)if(eligible.has(e.source)&&eligible.has(e.target)){adj.get(e.source).push(e.target);adj.get(e.target).push(e.source);}const seen=new Set(),components=[];for(const n of nodes){if(seen.has(n.id))continue;const ids=[],queue=[n.id];seen.add(n.id);while(queue.length){const i=queue.pop();ids.push(i);for(const j of adj.get(i))if(!seen.has(j)){seen.add(j);queue.push(j);}}components.push(ids);}return components;}
$('autogroup').addEventListener('click',()=>{if(!state.model)return;const components=connectedNodeGroups(state.model.nodes,state.model.edges);components.forEach((nodes,i)=>addGroup('Componente '+(i+1),nodes.flatMap(id=>state.model.nodes[id-1].members)));renderGroups();notify(`${components.length} componentes salvas como grupos.`);});
$('hotspots').addEventListener('click',()=>{if(!state.model)return;const info=colorInfo();if(!info.numeric){notify('Escolha uma cor numérica para encontrar hotspots.',true);return;}const sorted=info.values.filter(v=>v!=null).sort((a,b)=>a-b);if(!sorted.length)return;const threshold=sorted[Math.floor((sorted.length-1)*.75)];const nodes=state.model.nodes.filter((n,i)=>info.values[i]!=null&&info.values[i]>=threshold),components=connectedNodeGroups(nodes,state.model.edges);components.forEach((ids,i)=>addGroup('Hotspot '+(i+1)+' · '+$('color').selectedOptions[0].text,ids.flatMap(id=>state.model.nodes[id-1].members)));renderGroups();notify(`${components.length} hotspots do quartil superior salvos.`);});

function workspace(){const model=state.model;return {format:'JuliaTDAStudio',version:1,created_at:new Date().toISOString(),dataset:{name:state.dataset.name,columns:state.dataset.columns.map(c=>c.name),rows:state.dataset.rows},config:model?.config??readConfig(),groups:state.groups,models:state.models,selected:[...state.selected],positions:state.positions,view:state.view};}
async function importWorkspace(file){
  const revision=++state.revision;
  if(file.size>20*1024*1024)throw new Error('O workspace deve ter até 20 MB.');
  const doc=JSON.parse(await file.text());
  if(revision!==state.revision)return;
  if(doc.format!=='JuliaTDAStudio'||doc.version!==1||!Array.isArray(doc.dataset?.rows)||!Array.isArray(doc.dataset?.columns))throw new Error('Workspace inválido ou versão não suportada.');
  if(!Array.isArray(doc.groups)||!Array.isArray(doc.models)||doc.groups.length>500||doc.models.length>50)throw new Error('Grupos ou modelos inválidos no workspace.');
  for(const group of doc.groups)if(typeof group.name!=='string'||typeof group.id!=='string'||!Array.isArray(group.rows)||group.rows.some(i=>!Number.isInteger(i)||i<1||i>doc.dataset.rows.length))throw new Error('Grupo inválido no workspace.');
  doc.groups=doc.groups.map((g,i)=>({...g,rows:[...new Set(g.rows)],color:colors[i%colors.length]}));
  if(doc.positions&&(!Array.isArray(doc.positions)||!doc.positions.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y))))throw new Error('Posições inválidas no workspace.');
  const dataset=await api('/api/import',{name:doc.dataset.name,csv:toCSV(doc.dataset.rows,doc.dataset.columns)});
  if(revision!==state.revision)return;
  $('dataset').querySelector('option[value="imported"]')?.remove();$('dataset').append(option('imported',dataset.name));$('dataset').value='imported';
  await installDataset(dataset,doc);
  if(revision!==state.revision)return;
  if(!state.model)throw new Error($('toast').textContent||'Não foi possível reconstruir o modelo do workspace.');
  notify('Workspace aberto. Modelo reconstruído em Julia.');
}
