function exportSVG(){if(!state.model)return;const clone=$('graph').cloneNode(true);clone.setAttribute('xmlns',NS);clone.querySelectorAll('.node').forEach(n=>{const circle=n.querySelector('circle');circle.setAttribute('stroke','#fff');circle.setAttribute('stroke-width','2');n.removeAttribute('tabindex');});clone.querySelectorAll('.edge').forEach(e=>{e.setAttribute('stroke','#65748b');e.setAttribute('opacity','.35');});clone.querySelectorAll('.brush').forEach(b=>b.remove());clone.insertBefore(element('rect',{x:state.viewbox[0],y:state.viewbox[1],width:state.viewbox[2],height:state.viewbox[3],fill:$('theme').dataset.dark==='true'?'#19283a':'#fafcfe'}),clone.firstChild);download('mapper.svg',new XMLSerializer().serializeToString(clone),'image/svg+xml');}
function exportScript(){if(!state.dataset)return;const cfg=state.model?.config??readConfig(),literal=value=>JSON.stringify(value).replace(/\$/g,'\\$');const csv=toCSV(state.dataset.rows,state.dataset.columns.map(c=>c.name));const code=`# MapperStudio · generated ${new Date().toISOString()}\n# Run with: julia --project=/path/to/MapperStudio.jl analise.jl\nusing MapperStudio, JSON3\n\n# Dataset and settings are literal data, not executable user input.\nds = parse_csv(${literal(csv)}; name="Dados")\nconfig = JSON3.read(${literal(JSON.stringify(cfg))}, Dict{String,Any})\nmodel = analyze(ds, config)\nopen(joinpath(@__DIR__, "mapper.json"), "w") do io\n    JSON3.write(io, model)\nend\nprintln(model["summary"])\n`;download('analise.jl',code,'text/plain');notify('Script Julia exportado com os dados e configurações incorporados.');}
