const imagePanel=document.createElement('div');imagePanel.id='lab-image';imagePanel.className='lab-panel';imagePanel.hidden=true;imagePanel.innerHTML='<h2>Da imagem ao complexo cubical</h2><p>Importe uma imagem ou explore o anel de exemplo. A imagem é reduzida a até 96 × 96 pixels, mantendo a proporção.</p><div class="analysis-controls"><button id="choose-image" class="secondary">Importar imagem</button><label>Filtragem <select id="image-filtration"><option value="grayscale">Nível de cinza</option><option value="height">Altura da máscara</option><option value="radial">Radial da máscara</option><option value="dilation">Dilatação</option><option value="erosion">Erosão</option><option value="signed_distance">Distância assinada</option></select></label><label>Limiar da máscara <input id="image-cutoff" type="number" min="0" max="1" step="0.05" value="0.5"></label><label><span>Inverter</span><input id="image-invert" type="checkbox"></label><button id="run-image" class="primary">Calcular topologia da imagem</button></div><canvas id="image-preview" width="64" height="64" aria-label="Prévia da imagem analisada"></canvas><div id="image-output"></div>';$('view-lab').append(imagePanel);
