function previewImage(){const canvas=$('image-preview'),ctx=canvas.getContext('2d');canvas.width=imagePixels[0].length;canvas.height=imagePixels.length;const buffer=ctx.createImageData(canvas.width,canvas.height);imagePixels.forEach((row,y)=>row.forEach((v,x)=>{const i=(y*canvas.width+x)*4;buffer.data[i]=buffer.data[i+1]=buffer.data[i+2]=Math.round(255*v);buffer.data[i+3]=255;}));ctx.putImageData(buffer,0,0);}
imagePixels=Array.from({length:64},(_,y)=>Array.from({length:64},(_,x)=>{const d=Math.hypot(x-31.5,y-31.5);return d>13&&d<22?0:1;}));previewImage();
