$('run-image').addEventListener('click',()=>task($('run-image'),'Calculando persistência cubical…',async()=>{const result=await api('/api/image',{pixels:imagePixels,filtration:$('image-filtration').value,cutoff:Number($('image-cutoff').value),invert:$('image-invert').checked});$('image-output').innerHTML=`<p class="result-note">${esc(result.note)}</p><div class="result-metrics">${result.summary.map(s=>`<div><b>${s.features}</b>barras H${s.dimension}</div>`).join('')}</div><div class="plot-panel"><h2>Característica de Euler</h2><p>χ = componentes − laços, em cada escala</p><div id="image-euler"></div></div><div class="table-wrap"><table><thead><tr><th>Dimensão</th><th>Nascimento</th><th>Morte</th><th>Persistência</th></tr></thead><tbody>${result.bars.slice(0,200).map(b=>`<tr><td>H${b.dimension}</td><td>${fmt(b.birth)}</td><td>${b.death==null?'∞ / censurado':fmt(b.death)}</td><td>${fmt(b.persistence)}</td></tr>`).join('')}</tbody></table></div>`;const curve=result.euler,maxY=Math.max(1,...curve.values.map(Math.abs)),chart=chartFrame(680,260,'Escala deslocada','Euler χ');const min=Math.min(0,...curve.values),max=Math.max(1,...curve.values),y=v=>chart.y((v-min)/(max-min));for(let i=0;i<=4;i++)chart.svg.append(element('text',{x:chart.box.left-6,y:chart.y(i/4)+3,class:'chart-label','text-anchor':'end'},fmt(min+(max-min)*i/4,0)));chart.svg.append(element('polyline',{points:curve.values.map((v,i)=>`${chart.x(curve.scales[i]/result.threshold)},${y(v)}`).join(' '),fill:'none',stroke:'var(--ocean)','stroke-width':2}));$('image-euler').append(chart.svg);const b=document.createElement('button');b.className='secondary';b.textContent='Exportar persistência e Euler';b.addEventListener('click',()=>exportJSON('imagem-tda.json',result));$('image-output').append(b);status('Análise cubical concluída.');}));
